import assert from "node:assert/strict";
import test from "node:test";

import {
    CheckoutPriceCalculator,
    type CheckoutPriceRequest,
} from "./checkout-price-calculator.js";

const calculator = new CheckoutPriceCalculator();

function calculate(request: CheckoutPriceRequest): string {
    return calculator.calculate(request);
}

test("discounts only the item, adds expedited shipping, then taxes the subtotal", () => {
    assert.equal(
        calculate({
            itemPriceUsd: "100.00",
            discountRate: "0.10",
            taxRate: "0.05",
            shippingMethod: "expedited",
        }),
        "110.25",
    );
});

test("uses half-even rounding when the cent digit is even", () => {
    assert.equal(
        calculate({
            itemPriceUsd: "1.005",
            discountRate: "0",
            taxRate: "0",
            shippingMethod: "standard",
        }),
        "1.00",
    );
});

test("uses half-even rounding when the cent digit is odd", () => {
    assert.equal(
        calculate({
            itemPriceUsd: "1.015",
            discountRate: "0",
            taxRate: "0",
            shippingMethod: "standard",
        }),
        "1.02",
    );
});

test("keeps a decimal input exact through the calculation", () => {
    assert.equal(
        calculate({
            itemPriceUsd: "0.10",
            discountRate: "0",
            taxRate: "0",
            shippingMethod: "standard",
        }),
        "0.10",
    );
});

